import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Weapon reach and spacing","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/combat/reach-and-spacing.md","filePath":"en/guide/combat/reach-and-spacing.md"}'),r={name:"en/guide/combat/reach-and-spacing.md"};function d(s,e,o,l,c,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="weapon-reach-and-spacing" tabindex="-1">Weapon reach and spacing <a class="header-anchor" href="#weapon-reach-and-spacing" aria-label="Permalink to &quot;Weapon reach and spacing&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Experimental distances · Not implemented.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>A weapon can have a maximum reach and a different preferred fighting distance.</li><li>A spear threatens farther away but becomes less effective up close.</li><li>Skill does not invisibly lengthen a weapon.</li></ul><p><span id="at-a-glance"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>Meaning</th></tr></thead><tbody><tr><td>Reach</td><td>The farthest point the particular action can physically threaten.</td></tr><tr><td>Preferred range</td><td>The distance where the action handles best; being in range does not mean being at the best distance.</td></tr><tr><td>Footprint</td><td>A thrust, sweep or arc covers a different shape, not guaranteed extra hits.</td></tr><tr><td>Position</td><td>Facing, line of sight and target movement still matter. Lunge extends a strike without automatically moving you forward.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands</th></tr></thead><tbody><tr><td>Melee and ranged attacks already depend on distance</td><td>Give melee actions distinct reach, preferred ranges and shapes.</td></tr><tr><td>Closing with a ranged opponent changes the fight</td><td>Closing inside a long melee weapon’s preferred distance also becomes a tactical choice.</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>Move inside a spear’s comfortable range to pressure its handling, or step away while its wielder commits to Lunge. Either choice still needs timing.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/combat/weapons-and-damage.html">Weapons</a> · <a href="/Syrolands-Public/en/guide/combat/special-attacks.html">Special Attacks</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/combat/reach-and-spacing.html">Read the full design specification</a></p>',15)])])}const g=a(r,[["render",d]]);export{m as __pageData,g as default};
